
let h1Auth = null;
async function ensureH1Auth() {
  if (h1Auth) return h1Auth;
  h1Auth = await window.discordActivityReady;
  return h1Auth;
}
function activityProxyUrl(url) {
  const path = String(url || "");
  if (path.startsWith("/.proxy/")) return path;
  if (path.startsWith("/")) return `/.proxy${path}`;
  return path;
}
async function activityFetch(url, options={}) {
  const auth = await ensureH1Auth();
  const headers = new Headers(options.headers || {});
  headers.set("Authorization", `Bearer ${auth.accessToken}`);
  return fetch(activityProxyUrl(url), {...options, headers, cache:options.cache || "no-store"});
}


let h0VolumeStatus = null;

async function loadH0VolumeStatus() {
  try {
    const response = await fetch("/.proxy/api/h0/status", { cache:"no-store" });
    if (!response.ok) return;
    h0VolumeStatus = await response.json();

    const status = document.getElementById("status");
    if (status) {
      status.textContent =
        `💾 H.0.1 Volume: ${h0VolumeStatus.volumeDetected ? "Mounted" : "Local fallback"} • ` +
        `${h0VolumeStatus.players} saved players • ` +
        `${h0VolumeStatus.botReady ? "Discord bot connected" : "Bot login disabled/not ready"} • ` +
        `Activity writes OFF`;
    }
  } catch (error) {
    console.warn("H.0 status load failed:", error);
  }
}


