async function showHatchReveal(payload){
  const pet=payload?.pet;
  if(!pet) return;
  const modal=document.getElementById("hatchRevealModal");
  document.getElementById("hatchRevealArt").innerHTML=assetImage(pet.image?`/assets/pets/${pet.image}`:null,pet.icon||"🐾","hatch-pet-image");
  document.getElementById("hatchRevealName").textContent=pet.name||"New Companion";
  document.getElementById("hatchRevealMeta").textContent=`${pet.rarity||"Companion"} • ${pet.habitat||"Unknown Habitat"}`;
  document.getElementById("hatchRevealFlavor").textContent=pet.flavor||pet.description||"A new companion joins your hunt.";
  document.getElementById("hatchRevealAbility").textContent=pet.ability||"Companion Ability";
  document.getElementById("hatchRevealAbilityEffect").textContent=pet.abilityEffect||pet.description||"This companion will help you on future hunts.";
  document.getElementById("hatchRevealRewards").textContent=`⭐ +${Number(payload.pointsAwarded||0)} Hunter Points${payload.newDex?" • 📖 New PetDex discovery!":""}`;
  modal.classList.remove("hidden");
  const close=()=>modal.classList.add("hidden");
  document.getElementById("closeHatchReveal").onclick=close;
  document.getElementById("hatchRevealLater").onclick=close;
  document.getElementById("hatchRevealEquip").onclick=async()=>{
    const button=document.getElementById("hatchRevealEquip");
    button.disabled=true; button.textContent="Equipping…";
    const response=await activityFetch("/api/activity/pet/equip",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({petId:pet.id})});
    const result=await response.json();
    if(!response.ok){button.disabled=false;button.textContent="🐾 Equip New Pet";document.getElementById("status").textContent=`❌ ${result.error||"Could not equip pet."}`;return;}
    if(gameData?.ownedPets) gameData.ownedPets.forEach(x=>x.equipped=String(x.id)===String(pet.id));
    document.getElementById("status").textContent=`🐾 ${pet.name} is now your active companion!`;
    close(); renderHome(); renderPets(); renderDex();
  };
}

async function hatchActivityEgg(slot){
  const response=await activityFetch("/api/activity/egg/hatch",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({slot:Number(slot)})});
  let payload={};
  try { payload=await response.json(); } catch(error) {
    document.getElementById("status").textContent="❌ The hatch response could not be read.";
    return null;
  }
  if(!response.ok){document.getElementById("status").textContent=`❌ ${payload.error||"Could not hatch egg."}`;return null;}

  document.getElementById("status").textContent=`🐣 ${payload.pet.name} hatched! +${payload.pointsAwarded} Hunter Points`;

  // Show the reward immediately. A follow-up sync should never be able to
  // prevent the hatch reveal from appearing.
  await showHatchReveal(payload);

  // Optimistically place the new pet into the current Activity state so the
  // Pets tab updates instantly, even if the live-state refresh is delayed.
  if(payload.pet){
    gameData=gameData||{};
    gameData.ownedPets=Array.isArray(gameData.ownedPets)?gameData.ownedPets:[];
    if(!gameData.ownedPets.some(p=>String(p.id)===String(payload.pet.id))){
      gameData.ownedPets.push({...payload.pet,equipped:false,xp:Number(payload.pet.xp||0)});
    }
    currentPetFilter="All";
  }
  renderPets();
  renderDex();
  renderEggs();

  try {
    const syncRes=await activityFetch("/api/activity/sync");
    const sync=await syncRes.json();
    if(syncRes.ok&&sync.ok){
      hunter=sync.hunter;
      gameData=sync.phaseD;
      phaseG9Social={...(phaseG9Social||{}),eggs:Array.isArray(sync.eggs)?sync.eggs:[],incubatorSlots:Number(sync.incubators?.slots||1),incubations:Array.isArray(sync.incubators?.incubations)?sync.incubators.incubations:[],recentHunts:Array.isArray(sync.recentHunts)?sync.recentHunts:[]};
      applyLocalPetNames();
      currentPetFilter="All";
      renderHome(); renderPets(); renderDex(); renderEggs(); renderPetFilters();
    }
  } catch(error) {
    console.error("Post-hatch live sync failed:",error);
  }
  return payload;
}

async function refreshH2AEggData() {
  try {
    const response=await activityFetch("/api/activity/sync");
    const payload=await response.json();
    if(!response.ok || !payload.ok) throw new Error(payload.error||"Could not sync live egg data.");
    phaseG9Social={
      ...(phaseG9Social||{}),
      eggs:Array.isArray(payload.eggs)?payload.eggs:[],
      incubatorSlots:Number(payload.incubators?.slots||1),
      incubations:Array.isArray(payload.incubators?.incubations)?payload.incubators.incubations:[],
      recentHunts:Array.isArray(payload.recentHunts)?payload.recentHunts:[]
    };
    renderEggs();
  } catch(error) {
    console.error("Live egg sync failed:",error);
    const status=document.getElementById("status");
    if(status) status.textContent=`❌ Egg sync failed: ${error.message}`;
  }
}

let h2aEggTimer=null;
function renderEggs() {
  if(!phaseG9Social) return;
  if(h2aEggTimer) clearTimeout(h2aEggTimer);
  h2aEggTimer=setTimeout(()=>{
    if(currentScreen==="eggs") refreshH2AEggData();
  },10000);
  const eggs=Array.isArray(phaseG9Social.eggs)?phaseG9Social.eggs:[];
  const incubations=Array.isArray(phaseG9Social.incubations)?phaseG9Social.incubations:[];
  const slots=Number(phaseG9Social.incubatorSlots||1);

  const grid=document.getElementById("eggGrid");
  grid.innerHTML=eggs.length?eggs.map((egg,index)=>`
    <button class="egg-card" data-egg-index="${egg.inventoryIndex ?? index}">
      <div class="egg-card-art">
        ${egg.image?`<img class="egg-live-image" src="/assets/eggs/${egg.image}" onerror="this.replaceWith(document.createTextNode('${egg.icon||"🥚"}'))" alt="${egg.name}">`:(egg.icon||"🥚")}
      </div>
      <div class="egg-card-body">
        <span class="rarity-pill">${egg.rarity}</span>
        <h3>${egg.name}</h3>
        <p>Ready to incubate</p>
        <small>Click to place in an open incubator.</small>
      </div>
    </button>`).join("")
    :`<div class="empty-state">You do not own any eggs yet. Successful hunts can discover eggs.</div>`;

  grid.querySelectorAll("[data-egg-index]").forEach(btn=>{
    btn.onclick=async()=>{
      const response=await activityFetch("/api/activity/egg/incubate",{
        method:"POST",headers:{"Content-Type":"application/json"},
        body:JSON.stringify({inventoryIndex:Number(btn.dataset.eggIndex)})
      });
      const payload=await response.json();
      if(!response.ok) return document.getElementById("status").textContent=`❌ ${payload.error||"Could not incubate egg."}`;
      document.getElementById("status").textContent="🥚 Egg placed in the incubator!";
      await refreshH2AEggData();
    };
  });

  const first=incubations[0];
  document.getElementById("incubatorEggName").textContent=first?first.name:"No Egg Incubating";
  document.getElementById("incubatorEggIcon").innerHTML=first?assetImage(first.image?`/assets/eggs/${first.image}`:null,first.icon||"🥚","incubator-egg-image"):"🥚";
  document.getElementById("incubatorStatus").textContent=first
    ? `${incubations.length}/${slots} incubator slot${slots===1?"":"s"} in use`
    : `${incubations.length}/${slots} incubator slots in use`;

  const hatchBtn=document.getElementById("hatchEggBtn");
  if(!first){
    document.getElementById("incubatorProgressFill").style.width="0%";
    document.getElementById("incubatorTimeLeft").textContent="—";
    document.getElementById("incubatorPercent").textContent="0%";
    hatchBtn.classList.add("hidden");
  } else {
    const total=Math.max(1,Number(first.readyAt)-Number(first.startedAt));
    const remaining=Math.max(0,Number(first.readyAt)-Date.now());
    const pct=Math.min(100,Math.max(0,((Date.now()-Number(first.startedAt))/total)*100));
    document.getElementById("incubatorProgressFill").style.width=`${pct}%`;
    document.getElementById("incubatorTimeLeft").textContent=remaining<=0?"Ready":formatCountdown(remaining);
    document.getElementById("incubatorPercent").textContent=`${Math.floor(pct)}%`;

    if(first.ready){
      hatchBtn.classList.remove("hidden");
      hatchBtn.textContent=`🐣 Hatch ${first.name}`;
      hatchBtn.onclick=async()=>{ hatchBtn.disabled=true; try{ await hatchActivityEgg(first.slot); } finally { hatchBtn.disabled=false; } };
    } else hatchBtn.classList.add("hidden");
  }

  // Show every active slot below the main incubator card.
  let list=document.getElementById("h2aIncubatorList");
  if(!list){
    list=document.createElement("div");
    list.id="h2aIncubatorList";
    list.className="h2a-incubator-list";
    document.querySelector(".incubator-card")?.insertAdjacentElement("afterend",list);
  }
  list.innerHTML=incubations.length?incubations.map(x=>`
    <div class="h2a-incubator-row ${x.ready?"ready":""}">
      <span class="h2a-incubator-row-art">${assetImage(x.image?`/assets/eggs/${x.image}`:null,x.icon||"🥚","incubator-row-image")}</span>
      <div><b>Slot ${x.slot}: ${x.name}</b><small>${x.ready?"Ready to hatch":`${formatCountdown(Math.max(0,x.readyAt-Date.now()))} remaining`}</small></div>
      ${x.ready?`<button class="secondary h2a-hatch-slot" data-slot="${x.slot}">Hatch</button>`:""}
    </div>`).join("")
    :`<div class="empty-state">All incubators are empty.</div>`;
  list.querySelectorAll("[data-slot]").forEach(btn=>btn.onclick=async()=>{ btn.disabled=true; try{ await hatchActivityEgg(Number(btn.dataset.slot)); } finally { btn.disabled=false; } });
}

