function beginHuntFromZone(key) {
  activeHuntZone = phaseFHunting.zones.find(z => z.key === key);
  if (!activeHuntZone) return;

  huntAttemptNumber = 1;
  currentEncounter = applyLureToEncounter(activeHuntZone, weightedRandomMonster(activeHuntZone));
  selectedHuntMethod = null;
  selectedCaptureTool = null;
  currentRoll = null;
  rimebitSecondChanceUsed = false;

  populateEncounterPage();
  showHuntStep("encounter");
}

function returnToHuntOverview() {
  activeHuntZone = null;
  currentEncounter = null;
  selectedHuntMethod = null;
  selectedCaptureTool = null;
  document.getElementById("baitPicker").classList.add("hidden");
  updateHuntOverviewProfile();
  showHuntStep("overview");
}

function weightedRandomMonster(zone) {
  if (zone.key === "wildwood" && !firstHollowKingTestShown) {
    const hollowKing = zone.monsters.find(m => m.name === "The Hollow King");
    if (hollowKing) {
      firstHollowKingTestShown = true;
      return hollowKing;
    }
  }
  if (zone.monsters.length === 1) return zone.monsters[0];
  const weights = zone.monsters.map(m => {
    if (m.rarity === "Common") return 50;
    if (m.rarity === "Rare") return 28;
    if (m.rarity === "Epic") return 15;
    if (m.rarity === "Legendary") return 7;
    return 20;
  });
  let roll = Math.random() * weights.reduce((a,b)=>a+b,0);
  for (let i=0;i<zone.monsters.length;i++) {
    roll -= weights[i];
    if (roll <= 0) return zone.monsters[i];
  }
  return zone.monsters[0];
}


function setMonsterStageBackground(stageId, encounter, zoom="normal") {
  const stage = document.getElementById(stageId);
  if (!stage) return;

  const art = monsterArtSource(encounter);

  if (art) {
    const size = zoom === "zoomed" ? "145% auto" : zoom === "result" ? "cover" : "cover";
    const position = zoom === "zoomed" ? "center 33%" : zoom === "result" ? "center 25%" : "center 28%";

    stage.style.background =
      `linear-gradient(90deg, rgba(2,6,23,.72), rgba(2,6,23,.12) 28%, rgba(2,6,23,.08) 72%, rgba(2,6,23,.72)),` +
      `linear-gradient(180deg, rgba(2,6,23,.32), rgba(2,6,23,.03) 35%, rgba(2,6,23,.62)),` +
      `url("${art}") ${position} / ${size} no-repeat`;
    stage.dataset.monsterBackground = "loaded";
  } else {
    stage.style.background =
      `linear-gradient(rgba(5,10,18,.10),rgba(5,10,18,.18)),` +
      `url("/assets/backgrounds/hunt_battle.png") center / cover no-repeat`;
    stage.dataset.monsterBackground = "fallback";
  }
}

function populateArtTarget(imgId, fallbackId, encounter, mode="contain") {
  const img = document.getElementById(imgId);
  const fallback = document.getElementById(fallbackId);
  const art = monsterArtSource(encounter);
  if (art) {
    img.src = art;
    img.alt = `${encounter.name} art`;
    img.classList.remove("hidden");
    fallback.classList.add("hidden");
  } else {
    img.classList.add("hidden");
    fallback.classList.remove("hidden");
    fallback.textContent = encounter?.icon || "❔";
  }
}

function getDifficulty(chance) {
  if (chance >= 70) return "Low";
  if (chance >= 50) return "Moderate";
  if (chance >= 30) return "High";
  return "Extreme";
}

function getPossibleRewards(encounter) {
  const rewards = [];
  rewards.push({icon:"⭐", label:"Hunter Points", value:`+${encounter.points || 0}`});
  // Live tokens/items/eggs/event rewards will only appear when the real game actually generates them.
  return rewards;
}

function populateEncounterPage() {
  if (!activeHuntZone || !currentEncounter) return;
  const pet = ownedPet(activePetKey) || gameData.ownedPets[0];

  document.getElementById("encounterZoneType").textContent = activeHuntZone.subtitle.toUpperCase();
  document.getElementById("encounterZoneName").textContent = activeHuntZone.name;
  document.getElementById("encounterAttemptNumber").textContent = `Attempt ${huntAttemptNumber}`;

  setMonsterStageBackground("fullArtEncounter", currentEncounter, "normal");
  const encounterImg = document.getElementById("encounterMonsterImage");
  const encounterFallback = document.getElementById("encounterMonsterFallback");
  encounterImg.classList.add("hidden");
  encounterFallback.classList.add("hidden");

  document.getElementById("encounterMonsterName").textContent = currentEncounter.name;
  document.getElementById("encounterMonsterRarity").textContent = currentEncounter.rarity;
  document.getElementById("encounterCatchChance").textContent = `${currentEncounter.baseChance}%`;
  document.getElementById("encounterHabitat").textContent = activeHuntZone.name;
  document.getElementById("encounterDifficulty").textContent = getDifficulty(currentEncounter.baseChance);
  const encounterPetName=document.getElementById("encounterPetName");
  encounterPetName.textContent = pet ? petDisplayName(pet) : "None";
  if (pet) encounterPetName.title = (pet.abilities||[]).map(a=>`${a.name} Rank ${a.rankRoman||a.rank}: ${a.effect}`).join(" | ");
  document.getElementById("encounterDescription").textContent =
    currentEncounter.name === "The Hollow King"
      ? "A dread monarch of the dead, ruler of forgotten souls and shattered thrones."
      : `A ${currentEncounter.rarity.toLowerCase()} creature has appeared in ${activeHuntZone.name}.`;

  const levelTag = document.getElementById("encounterMonsterLevel");
  if (currentEncounter.level) {
    levelTag.textContent = `Level ${currentEncounter.level}`;
    levelTag.classList.remove("hidden");
  } else {
    levelTag.classList.add("hidden");
  }

  document.getElementById("possibleRewards").innerHTML =
    getPossibleRewards(currentEncounter).map(r => `
      <div class="possible-reward-row"><span>${r.icon} ${r.label}</span><b>${r.value}</b></div>
    `).join("") || `<div class="possible-reward-row"><span>🎒 Rewards</span><b>Varies</b></div>`;

  document.getElementById("baitPicker").classList.add("hidden");
}

function openBaitPicker() {
  selectedHuntMethod = "bait";
  const picker = document.getElementById("baitPicker");
  picker.classList.remove("hidden");

  const grid = document.getElementById("captureToolGrid");
  const baitTools = phaseFHunting.captureTools.filter(t => t.key !== "none");
  grid.innerHTML = baitTools.map(tool => {
    const uses = localToolUses[tool.key];
    const unavailable = uses === 0;
    return `
      <button class="capture-tool" data-tool="${tool.key}" ${unavailable ? "disabled" : ""}>
        <span class="tool-icon">${tool.icon}</span>
        <strong>${tool.name}</strong>
        <small>${tool.bonus >= 100 ? "Guaranteed DEV catch" : `+${tool.bonus}% catch chance`}</small>
        <small>${uses === null ? "Unlimited" : `${uses} left in DEV`}</small>
      </button>
    `;
  }).join("");

  grid.querySelectorAll("[data-tool]").forEach(btn => {
    btn.onclick = () => chooseHuntMethod(btn.dataset.tool);
  });

  picker.scrollIntoView({behavior:"smooth", block:"nearest"});
}

function chooseHuntMethod(toolKey) {
  const tool = phaseFHunting.captureTools.find(t => t.key === toolKey);
  if (!tool || !currentEncounter) return;
  if (localToolUses[toolKey] === 0) return;

  selectedCaptureTool = tool;
  selectedHuntMethod = toolKey === "none" ? "normal" : "bait";
  populateAttemptPage();
  showHuntStep("attempt");
}

function populateAttemptPage() {
  const tool = selectedCaptureTool || phaseFHunting.captureTools[0];
  const chance = Math.min(100, currentEncounter.baseChance + Number(tool.bonus || 0));
  const pet = ownedPet(activePetKey) || gameData.ownedPets[0];

  document.getElementById("attemptZoneName").textContent = activeHuntZone.name;
  document.getElementById("attemptChancePill").textContent = `${chance}%`;

  setMonsterStageBackground("attemptArtStage", currentEncounter, "zoomed");
  document.getElementById("attemptMonsterImage").classList.add("hidden");
  document.getElementById("attemptMonsterFallback").classList.add("hidden");

  document.getElementById("attemptMonsterName").textContent = currentEncounter.name;
  document.getElementById("attemptMonsterRarity").textContent = currentEncounter.rarity;
  document.getElementById("attemptCatchChance").textContent = `${chance}%`;
  document.getElementById("attemptHunterLevel").textContent = hunter.level;
  document.getElementById("attemptPetName").textContent = pet ? petDisplayName(pet) : "None";
  document.getElementById("attemptMethodName").textContent = tool.name;
  document.getElementById("attemptRarityInfo").textContent = currentEncounter.rarity;
  document.getElementById("attemptLevelInfo").textContent = currentEncounter.level || "—";
  document.getElementById("attemptPointsInfo").textContent = `+${currentEncounter.points || 0}`;
  document.getElementById("attemptTokensInfo").textContent = (activeHuntZone.key === "biggame" && currentEncounter.tokens) ? `+${currentEncounter.tokens}` : "—";
  document.getElementById("rollTargetLabel").textContent = `Need ≤ ${chance}`;
  document.getElementById("rollMeterFill").style.width = `${chance}%`;

  const levelTag = document.getElementById("attemptMonsterLevel");
  if (currentEncounter.level) {
    levelTag.textContent = `Level ${currentEncounter.level}`;
    levelTag.classList.remove("hidden");
  } else {
    levelTag.classList.add("hidden");
  }

  document.getElementById("performCaptureBtn").onclick = performCapture;
}

function performCapture() {
  if (!currentEncounter || !selectedCaptureTool) return;

  const tool = selectedCaptureTool;
  const chance = Math.min(100, currentEncounter.baseChance + Number(tool.bonus || 0));

  if (localToolUses[tool.key] !== null && localToolUses[tool.key] > 0) {
    localToolUses[tool.key]--;
  }

  currentRoll = Math.floor(Math.random() * 100) + 1;
  const success = chance >= 100 || currentRoll <= chance;

  if (success) {
    showCaptureSuccess(currentRoll, chance, tool);
  } else {
    maybeUseRimebitSecondChance(currentRoll, chance, tool);
  }
}

function maybeUseRimebitSecondChance(roll, chance, tool) {
  // DEV demo rate remains intentionally high.
  if (!rimebitSecondChanceUsed && Math.random() < 0.55) {
    rimebitSecondChanceUsed = true;
    document.getElementById("attemptFlavor").textContent =
      `❄️ Rimebit froze the fleeing creature! Your roll was ${roll}; you get one Second Chance reroll.`;
    const btn = document.getElementById("performCaptureBtn");
    btn.textContent = "❄️ Rimebit: Reroll Catch";
    btn.onclick = performRimebitReroll;
  } else {
    showCaptureFailure(roll, chance);
  }
}

function performRimebitReroll() {
  const tool = selectedCaptureTool;
  const chance = Math.min(100, currentEncounter.baseChance + Number(tool.bonus || 0));
  currentRoll = Math.floor(Math.random() * 100) + 1;

  if (currentRoll <= chance) showCaptureSuccess(currentRoll, chance, tool, true);
  else showCaptureFailure(currentRoll, chance, true);
}

function populateResultArtwork() {
  setMonsterStageBackground("resultArtStage", currentEncounter, "result");
  document.getElementById("resultMonsterImage").classList.add("hidden");
  document.getElementById("resultMonsterFallback").classList.add("hidden");
}

function showCaptureSuccess(roll, chance, tool, secondChance=false) {
  populateResultArtwork();

  const pointReward = Number(currentEncounter.points || 0);

  document.getElementById("resultStatusIcon").textContent = "🏆";
  document.getElementById("resultZoneName").textContent = activeHuntZone.name;
  document.getElementById("huntResultTitle").textContent = `🎉 ${currentEncounter.name} Caught!`;
  document.getElementById("huntResultText").textContent =
    `${secondChance ? "Rimebit's Second Chance worked! " : ""}Roll ${roll} succeeded against a ${chance}% DEV catch chance using ${tool.name}.`;

  const rewards = [
    `<div><span>⭐ Hunter Points</span><b>+${pointReward}</b></div>`
  ];

  if (activeHuntZone.key === "biggame" && currentEncounter.tokens) {
    rewards.push(`<div><span>🪙 Hunt Tokens</span><b>+${currentEncounter.tokens}</b></div>`);
  }

  if (activeHuntZone.key === "distortion") {
    rewards.push(`<div><span>🌀 Distortion Rewards</span><b>Shown only if actually rolled</b></div>`);
  }

  if (activeHuntZone.key === "bounty") {
    rewards.push(`<div><span>📜 Bounty Rewards</span><b>Shown only if actually earned</b></div>`);
  }

  document.getElementById("huntResultRewards").innerHTML = rewards.join("");

  document.getElementById("huntResultDetails").innerHTML = `
    <div><span>Catch Chance</span><b>${chance}%</b></div>
    <div><span>Roll</span><b>${roll}</b></div>
    <div><span>Method</span><b>${tool.name}</b></div>
    <div><span>Rarity</span><b>${currentEncounter.rarity}</b></div>
    <div><span>Active Pet</span><b>${petDisplayName(ownedPet(activePetKey) || gameData.ownedPets[0])}</b></div>
    ${secondChance ? `<div><span>Companion Effect</span><b>Second Chance</b></div>` : ""}
  `;

  document.getElementById("huntAgainBtn").textContent = "🏹 Hunt Again";
  document.getElementById("huntAgainBtn").onclick = resetEncounterForNextHunt;
  showHuntStep("result");
}

function showCaptureFailure(roll, chance, secondChance=false) {
  populateResultArtwork();

  document.getElementById("resultStatusIcon").textContent = "💨";
  document.getElementById("resultZoneName").textContent = activeHuntZone.name;
  document.getElementById("huntResultTitle").textContent = "💨 The Creature Escaped";
  document.getElementById("huntResultText").textContent =
    `${secondChance ? "Even after Rimebit's Second Chance, " : ""}roll ${roll} missed the ${chance}% DEV catch chance.`;

  document.getElementById("huntResultRewards").innerHTML = `
    <div><span>🧪 Live rewards</span><b>None changed</b></div>
  `;

  document.getElementById("huntResultDetails").innerHTML = `
    <div><span>Catch Chance</span><b>${chance}%</b></div>
    <div><span>Roll</span><b>${roll}</b></div>
    <div><span>Method</span><b>${selectedCaptureTool?.name || "Normal Hunt"}</b></div>
    <div><span>Rarity</span><b>${currentEncounter.rarity}</b></div>
    ${secondChance ? `<div><span>Companion Effect</span><b>Second Chance used</b></div>` : ""}
  `;

  document.getElementById("huntAgainBtn").textContent = "🏹 Hunt Again";
  document.getElementById("huntAgainBtn").onclick = resetEncounterForNextHunt;

  showHuntStep("result");
}

function resetEncounterForNextHunt() {
  if (!activeHuntZone) {
    returnToHuntOverview();
    return;
  }

  huntAttemptNumber++;
  currentEncounter = weightedRandomMonster(activeHuntZone);
  selectedCaptureTool = null;
  selectedHuntMethod = null;
  currentRoll = null;
  rimebitSecondChanceUsed = false;

  document.getElementById("attemptFlavor").textContent = "You steady yourself and prepare for the hunt…";
  document.getElementById("performCaptureBtn").textContent = "🎲 Roll to Catch";

  populateEncounterPage();
  showHuntStep("encounter");
}

function formatCountdown(ms) {
  ms = Math.max(0, Number(ms) || 0);
  const total = Math.floor(ms / 1000);
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const s = total % 60;
  return `${String(h).padStart(2,"0")}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}`;
}

function switchEventView(view) {
  document.querySelectorAll(".event-tab").forEach(b => b.classList.toggle("active", b.dataset.eventView === view));
  document.querySelectorAll("[data-event-view-panel]").forEach(p => p.classList.toggle("active", p.dataset.eventViewPanel === view));
}

function setupEventNavigation() {
  document.querySelectorAll(".event-tab").forEach(b => {
    b.onclick = () => switchEventView(b.dataset.eventView);
  });
  document.querySelectorAll("[data-open-event]").forEach(b => {
    b.onclick = () => switchEventView(b.dataset.openEvent);
  });
}

let h2cEventRefreshTimer=null;

async function refreshH2CLiveEvents(showErrors=false){
  try{
    const response=await activityFetch("/api/activity/live-events");
    const payload=await response.json();
    if(!response.ok) throw new Error(payload.error||"Could not load live events.");
    h2aLiveEvents=payload;
    renderPhaseEEvents();
    syncH2CBigGameWallet();
    return payload;
  }catch(error){
    if(showErrors) showActivityResult("❌","Event Sync Failed",error.message);
    return null;
  }
}

function syncH2CBigGameWallet(){
  const big=h2aLiveEvents?.bigGame;
  if(!big) return;
  const liveTokens=Number(big.tokenBalance||0);
  const wallet=document.getElementById("tokens");
  if(wallet) wallet.textContent=liveTokens;
  if(hunter) hunter.tokens=liveTokens;
}

function renderPhaseEEvents() {
  if(!h2aLiveEvents) return;
  setupEventNavigation();

  const active=Array.isArray(h2aLiveEvents.active)?h2aLiveEvents.active:[];
  const overview=document.querySelector(".event-overview-grid");
  if(overview){
    overview.innerHTML=active.length?active.map(event=>`
      <button class="event-summary ${event.key}-summary" ${event.key==="biggame"?`data-open-event="biggame"`:""}>
        <div class="event-summary-art">${event.icon||"⚔️"}</div>
        <div><span class="live-dot">ACTIVE</span><h3>${event.name}</h3>
        <p>${event.endsAt?`${formatCountdown(Math.max(0,event.endsAt-Date.now()))} remaining`:event.type}</p>
        <small>${event.description||""}</small></div>
      </button>`).join("")
      :`<section class="panel"><h3>🌙 No Special Events Active</h3><p class="muted">Normal hunting is currently available. Special event hunting options appear here only while they are actually live.</p></section>`;
  }

  const focus=document.querySelector(".season-focus-card");
  if(focus){
    focus.querySelector(".eyebrow").textContent="LIVE WORLD STATUS";
    focus.querySelector("h3").textContent=active.length?`${active.length} Active Event${active.length===1?"":"s"}`:"Normal Hunting";
    const pills=focus.querySelector(".focus-pills");
    if(pills) pills.innerHTML=active.length?active.map(e=>`<span>${e.icon} ${e.name}</span>`).join(""):`<span>🏹 Normal Hunts Available</span>`;
    const muted=focus.querySelector(".muted");
    if(muted) muted.textContent="Only currently active Monster Hunt events are displayed in the Activity.";
  }

  const big=h2aLiveEvents.bigGame;
  const bigTab=document.querySelector('[data-event-view="biggame"]');
  const bigPanel=document.querySelector('[data-event-view-panel="biggame"]');
  bigTab?.classList.toggle("hidden",!big?.active);
  bigPanel?.classList.toggle("hidden",!big?.active);

  // H.2C intentionally keeps systems that are not yet live in the Activity hidden.
  document.querySelector('[data-event-view="bounty"]')?.classList.add("hidden");
  document.querySelector('[data-event-view-panel="bounty"]')?.classList.add("hidden");
  document.querySelector('[data-event-view="distortion"]')?.classList.add("hidden");
  document.querySelector('[data-event-view-panel="distortion"]')?.classList.add("hidden");

  if(big?.active){
    document.getElementById("bigGameScore").textContent=`${Number(big.playerScore||0)} 🪙`;
    document.getElementById("bigGameWallet").textContent=`${Number(big.tokenBalance||0)} 🪙`;
    document.getElementById("bigGameRank").textContent=big.playerRank?`#${big.playerRank}`:"—";
    document.getElementById("bigGameCooldown").textContent=`${Math.round(Number(big.huntCooldownMs||0)/60000)} min`;

    const rows=big.leaderboard||[];
    document.getElementById("bigGameLeaderboard").innerHTML=rows.length?rows.map((entry,i)=>`
      <div class="leaderboard-row">
        <div class="rank-medal">${["🥇","🥈","🥉"][i]||`#${i+1}`}</div>
        <div><b>${entry.name}</b>${false?`<small class="you-tag">YOU</small>`:""}</div>
        <div class="leader-score">${entry.score} 🪙</div>
      </div>`).join("")
      :`<div class="empty-state">No successful catches yet. The board is wide open.</div>`;

    document.getElementById("bigGameTokenRewards").innerHTML=Object.entries(big.tokenRewards||{}).map(([rarity,value])=>
      `<div class="reward-chip"><span>${rarity}</span><b>+${value} 🪙</b></div>`
    ).join("");

    const placements=big.placementRewards||[50,30,15];
    document.getElementById("bigGamePlacementRewards").innerHTML=
      `<span>🥇 +${placements[0]||50} points</span><span>🥈 +${placements[1]||30}</span><span>🥉 +${placements[2]||15}</span>`;

    updateH2CBigGameTimers();
    const btn=document.getElementById("liveBigGameHunt");
    if(btn){
      btn.onclick=()=>{
        if(btn.disabled) return;
        navTo("hunt");
      };
    }
  }else if(currentScreen==="events"){
    switchEventView("overview");
  }

  setupEventNavigation();
}

function updateH2CBigGameTimers(){
  const big=h2aLiveEvents?.bigGame;
  if(!big?.active) return;
  const now=Date.now();
  const remaining=Math.max(0,Number(big.endsAt||0)-now);
  const timer=document.getElementById("bigGameTimer");
  if(timer) timer.textContent=`${formatCountdown(remaining)} remaining`;

  const summary=document.querySelector('.event-summary.biggame-summary p');
  if(summary) summary.textContent=`${formatCountdown(remaining)} remaining`;

  const readyAt=Number(big.huntReadyAt||0);
  const wait=Math.max(0,readyAt-now);
  const status=document.getElementById("bigGameHuntStatus");
  const readyText=document.getElementById("bigGameHuntReadyText");
  const btn=document.getElementById("liveBigGameHunt");

  if(wait<=0){
    if(status) status.textContent="✅ Ready to Hunt";
    if(readyText) readyText.textContent="Your Big Game hunt is ready now.";
    if(btn){btn.disabled=false;btn.textContent="🏹 Hunt Now";}
  }else{
    if(status) status.textContent=`⏳ Ready in ${formatCountdown(wait)}`;
    if(readyText) readyText.textContent="Big Game uses the event's live 30-minute hunt cooldown.";
    if(btn){btn.disabled=true;btn.textContent=`⏳ ${formatCountdown(wait)}`;}
  }

  if(remaining<=0 && currentScreen==="events"){
    refreshH2CLiveEvents(false);
  }
}

function startEventTimers() {
  if (timerInterval) clearInterval(timerInterval);
  timerInterval=setInterval(updateH2CBigGameTimers,1000);

  if(h2cEventRefreshTimer) clearInterval(h2cEventRefreshTimer);
  h2cEventRefreshTimer=setInterval(()=>{
    if(currentScreen==="events") refreshH2CLiveEvents(false);
  },5000);
}

function preloadEmbeddedMonsterArt() {
  Object.values(EMBEDDED_MONSTER_ART).forEach(src => {
    const img = new Image();
    img.src = src;
  });
}

async function boot() {
  preloadEmbeddedMonsterArt();
  try { await ensureH1Auth(); } catch (error) {
    document.getElementById("status").textContent = `❌ Discord Activity login failed: ${error.message}. H.1.1 uses the Discord Activity proxy route.`;
    return;
  }
  try {
    const [hunterRes,dataRes,eventRes,huntRes,alignRes,leaderRes,socialRes,liveEventsRes] = await Promise.all([
      activityFetch("/api/test-hunter"),
      activityFetch("/api/phase-d-data"),
      activityFetch("/api/phase-e-events"),
      activityFetch("/api/phase-f-hunting"),
      activityFetch("/api/phase-g-alignment"),
      activityFetch("/api/phase-g5-leaderboards"),
      activityFetch("/api/phase-g9-social"),
      activityFetch("/api/activity/live-events")
    ]);
    if (!hunterRes.ok || !dataRes.ok || !eventRes.ok || !huntRes.ok || !alignRes.ok || !leaderRes.ok || !socialRes.ok || !liveEventsRes.ok) throw new Error("Failed to load live Monster Hunt data.");
    hunter = await hunterRes.json();
    gameData = await dataRes.json();
    phaseEEvents = await eventRes.json();
    phaseFHunting = await huntRes.json();
    phaseGAlignment = await alignRes.json();
    phaseG5Leaderboards = await leaderRes.json();
    phaseG9Social = await socialRes.json();
    h2aLiveEvents = await liveEventsRes.json();
    applyLocalPetNames();

    document.getElementById("hunterName").textContent=hunter.name;
    document.getElementById("hunterTitle").textContent=hunter.title;
    document.getElementById("level").textContent=hunter.level;
    document.getElementById("points").textContent=hunter.points;
    document.getElementById("tokens").textContent=hunter.tokens;
    document.getElementById("petsCount").textContent=`${gameData.ownedPets.length} owned`;
    document.getElementById("ownedPetCount").textContent=gameData.ownedPets.length;
    document.getElementById("petdexCount").textContent=hunter.stats.petDex;
    document.getElementById("dexProgress").textContent=hunter.stats.petDex;
    document.getElementById("trophyCount").textContent=`${hunter.stats.trophies} trophies`;

    playerProgress={
      level:Number(hunter.level)||0,
      trophies:Number(hunter.stats.trophies)||0,
      petdex:Number(String(hunter.stats.petDex).split("/")[0])||0
    };

    const ownedKeys=new Set(gameData.ownedPets.map(p=>p.key));
    if (!ownedKeys.has(activePetKey)) activePetKey=hunter.activePetKey;

    renderMainAvatar();
    renderPetFilters();
    renderPetProgressionBanner();
    renderPets();
    renderDex();
    renderInventoryFilters();
    renderInventory();
    renderCollection();
    renderActivePet();

    renderHomeLeaderboard();
    renderPhaseEEvents();
    renderPhaseFHunting();
  requestAnimationFrame(applyG9Backgrounds);
    startEventTimers();

    document.getElementById("status").textContent="✅ Phase H.2A.4 loaded. Fresh-season wipe rules and admin testing bypass are active.";
  } catch (err) {
    console.error(err);
    document.getElementById("status").textContent="❌ Phase D DEV data failed to load.";
  }
}

document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeCustomizer();closeDetail();}});

// ==================== PHASE H.1 LIVE OVERRIDES ====================
renderLureSelector = function() {
  const grid = document.getElementById("lureGrid");
  if (!grid || !hunter) return;
  const bait = hunter.bait || {rare:0,epic:0,legendary:0};
  const lures = [
    {key:"none",name:"No Lure",icon:"🏹",count:null,desc:"Use normal encounter odds."},
    {key:"rare",name:"Rare Bait",icon:"🔵",count:Number(bait.rare||0),desc:"Improves Rare odds."},
    {key:"epic",name:"Epic Bait",icon:"🟣",count:Number(bait.epic||0),desc:"Improves Epic odds."},
    {key:"legendary",name:"Legendary Bait",icon:"🟠",count:Number(bait.legendary||0),desc:"Improves Legendary odds."}
  ];
  selectedLureKey = hunter.activeBait || "none";
  grid.innerHTML = lures.map(x => `
    <button class="lure-card ${selectedLureKey===x.key?"selected":""}" data-lure="${x.key}" ${x.count===0?"disabled":""}>
      <span class="lure-icon">${x.icon}</span><div><b>${x.name}</b><small>${x.desc}</small><small class="lure-uses">${x.count===null?"Normal Hunt":`${x.count} owned`}</small></div>
    </button>`).join("");
  document.getElementById("selectedLureName").textContent = lures.find(x=>x.key===selectedLureKey)?.name || "No Lure";
  grid.querySelectorAll("[data-lure]").forEach(btn => btn.onclick = async () => {
    const response = await activityFetch("/api/activity/bait", {
      method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({type:btn.dataset.lure})
    });
    const payload = await response.json();
    if (!response.ok) return document.getElementById("status").textContent = `❌ ${payload.error}`;
    hunter.activeBait = payload.activeBait;
    hunter.bait = payload.bait;
    renderLureSelector();
  });
};

renderPhaseFHunting = function() {
  if (!hunter) return;
  updateHuntOverviewProfile();
  renderLureSelector();

  const grid = document.getElementById("huntZoneGrid");
  const remaining = Math.max(0, Number(hunter.huntReadyAt || 0) - Date.now());
  const ready = remaining <= 0;
  const big=h2aLiveEvents?.bigGame;
  const bigActive=Boolean(big?.active && Number(big.endsAt||0)>Date.now());
  const normalLabel=bigActive?"Normal / Big Game Hunt":"Normal Hunt";
  const normalEyebrow=bigActive?"🎯 BIG GAME ACTIVE":"NORMAL HUNT";
  const normalCopy=bigActive
    ? (ready
      ? `Big Game is live! Successful catches award Hunt Tokens and count toward the live leaderboard.`
      : `Big Game is live. Your next event hunt is ready in ${formatCountdown(remaining)}.`)
    : (ready
      ? "Track a real monster using your new-season account."
      : `Ready in ${formatCountdown(remaining)}.`);

  grid.innerHTML = `
    ${bigActive?`
    <button class="hunt-zone-card live-big-game-hunt-card" id="liveBigGameHuntCard" ${ready?"":"disabled"}>
      <div class="hunt-zone-art">🎯</div>
      <div class="hunt-zone-body">
        <p class="eyebrow">LIVE EVENT</p>
        <h3>${ready?"Big Game Hunt":"Big Game Cooldown"}</h3>
        <p>${ready
          ? `Hunt now • Successful catches award event Hunt Tokens • ${Number(big.playerScore||0)} 🪙 earned this event`
          : `Ready in ${formatCountdown(remaining)} • ${Number(big.playerScore||0)} 🪙 earned this event`}</p>
      </div>
    </button>`:""}
    <button class="hunt-zone-card live-normal-hunt-card" id="liveNormalHuntBtn" ${ready?"":"disabled"}>
      <div class="hunt-zone-art">🏹</div>
      <div class="hunt-zone-body"><p class="eyebrow">${normalEyebrow}</p><h3>${ready?normalLabel:"Hunt Cooldown"}</h3>
      <p>${normalCopy}</p></div>
    </button>`;

  const normalBtn=document.getElementById("liveNormalHuntBtn");
  if (ready && normalBtn) normalBtn.onclick = () => beginHuntFromZone(bigActive?"biggame":"normal");
  const bigBtn=document.getElementById("liveBigGameHuntCard");
  if (ready && bigBtn) bigBtn.onclick = () => beginHuntFromZone("biggame");

  localToolUses = {none:null, ...(hunter.captureItems || {})};
  document.getElementById("encounterBackBtn").onclick = returnToHuntOverview;
  document.getElementById("encounterLeaveBtn").onclick = returnToHuntOverview;
  document.getElementById("attemptBackBtn").onclick = () => showHuntStep("encounter");
  document.getElementById("resultOverviewBtn").onclick = returnToHuntOverview;
  document.getElementById("normalHuntChoice").onclick = () => chooseHuntMethod("none");
  document.getElementById("baitHuntChoice").onclick = openBaitPicker;
  showHuntStep("overview");
};

beginHuntFromZone = async function(zoneKey="normal") {
  const response = await activityFetch("/api/activity/hunt/start", {
    method:"POST", headers:{"Content-Type":"application/json"}, body:"{}"
  });
  const payload = await response.json();
  if (!response.ok || !payload.ok) {
    if (payload.code === "cooldown") {
      hunter.huntReadyAt = payload.readyAt;
      renderPhaseFHunting();
      return;
    }
    return document.getElementById("status").textContent = `❌ ${payload.error || payload.message || "Could not start hunt."}`;
  }

  const bigGameHunt=zoneKey==="biggame" && Boolean(h2aLiveEvents?.bigGame?.active);
  activeHuntZone = {
    key:bigGameHunt?"biggame":"normal",
    name:payload.monster.habitat || "Hunting Grounds",
    subtitle:bigGameHunt?"Big Game Hunt":"Normal Hunt"
  };
  huntAttemptNumber = 1;
  currentEncounter = {
    ...payload.monster,
    baseChance:payload.baseChance,
    image:payload.monster.imageUrl || (payload.monster.image ? `/assets/monsters/${payload.monster.image}` : null)
  };
  hunter = {...hunter,...payload.player};
  phaseFHunting.captureTools = payload.choices.map(c => ({
    key:c.itemKey || "none",
    name:c.itemKey ? c.label : "Normal Hunt",
    icon:c.itemKey==="berry"?"🍓":c.itemKey==="honey"?"🍯":c.itemKey==="net"?"🕸️":c.itemKey==="masterCharm"?"🌟":"🏹",
    bonus:0, uses:c.itemKey ? Number(hunter.captureItems?.[c.itemKey]||0) : null, liveChance:c.chance
  }));
  populateEncounterPage();
  document.getElementById("encounterCatchChance").textContent = `${payload.chance}%`;
  showHuntStep("encounter");
};

openBaitPicker = function() {
  const picker = document.getElementById("baitPicker");
  picker.classList.remove("hidden");
  const tools = (phaseFHunting.captureTools || []).filter(t => t.key !== "none");
  const grid = document.getElementById("captureToolGrid");
  grid.innerHTML = tools.length ? tools.map(t => `
    <button class="capture-tool" data-tool="${t.key}">
      <span class="tool-icon">${t.icon}</span><strong>${t.name}</strong>
      <small>${t.liveChance}% final catch chance</small><small>${Number(hunter.captureItems?.[t.key]||0)} owned</small>
    </button>`).join("") : `<div class="empty-state">You do not own any capture items. Use Hunt Normally.</div>`;
  grid.querySelectorAll("[data-tool]").forEach(btn => btn.onclick = () => chooseHuntMethod(btn.dataset.tool));
};

const _h1OldPopulateAttemptPage = populateAttemptPage;
populateAttemptPage = function() {
  _h1OldPopulateAttemptPage();
  if (selectedCaptureTool?.liveChance != null) {
    const chance = Number(selectedCaptureTool.liveChance);
    document.getElementById("attemptChancePill").textContent = `${chance}%`;
    document.getElementById("attemptCatchChance").textContent = `${chance}%`;
    document.getElementById("rollTargetLabel").textContent = `Need ≤ ${chance}`;
    document.getElementById("rollMeterFill").style.width = `${chance}%`;
  }
  const btn=document.getElementById("performCaptureBtn");
  if(btn){
    btn.disabled=false;
    btn.textContent="🎲 Roll to Catch";
    btn.onclick=livePerformCapture;
  }
};

async function livePerformCapture() {
  if (!currentEncounter || !selectedCaptureTool) return;
  const btn = document.getElementById("performCaptureBtn");
  btn.disabled = true; btn.textContent = "🎲 Resolving Hunt…";
  const itemKey = selectedCaptureTool.key === "none" ? null : selectedCaptureTool.key;
  try {
    const status=document.getElementById("status");
    if(status) status.textContent="🎲 Resolving your live capture...";
    const response = await activityFetch("/api/activity/hunt/capture", {
      method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({itemKey})
    });
    const payload = await response.json();
    if (!response.ok || !payload.ok) {
      document.getElementById("status").textContent = `❌ ${payload.error || payload.message}`;
      return;
    }
    hunter = {...hunter,...payload.player};
    populateResultArtwork();
    document.getElementById("resultStatusIcon").textContent = payload.caught ? "🏆" : "💨";
    document.getElementById("huntResultTitle").textContent = payload.caught ? `🎉 ${currentEncounter.name} Caught!` : `💨 ${currentEncounter.name} Escaped`;
    document.getElementById("huntResultText").textContent = `Roll ${payload.roll ?? "—"} • ${payload.chance}% catch chance • ${payload.method}`;

    const rewards = [];
    if (payload.rewards.points) rewards.push(`<div><span>⭐ Hunter Points</span><b>+${payload.rewards.points}</b></div>`);
    if (payload.rewards.tokens) rewards.push(`<div><span>🪙 Hunt Tokens</span><b>+${payload.rewards.tokens}</b></div>`);
    if (payload.rewards.eggs) rewards.push(`<div><span>🥚 Eggs Found</span><b>+${payload.rewards.eggs}</b></div>`);
    if (!rewards.length) rewards.push(`<div><span>${payload.caught?"✅ Capture":"📚 Encounter"}</span><b>${payload.caught?"Recorded":"Knowledge gained"}</b></div>`);
    document.getElementById("huntResultRewards").innerHTML = rewards.join("");
    document.getElementById("huntResultDetails").innerHTML = `
      <div><span>Catch Chance</span><b>${payload.chance}%</b></div>
      <div><span>Roll</span><b>${payload.roll ?? "—"}</b></div>
      <div><span>Method</span><b>${payload.method}</b></div>
      <div><span>Rarity</span><b>${currentEncounter.rarity}</b></div>
      <div><span>Discord Update</span><b>Sent</b></div>`;
    document.getElementById("huntAgainBtn").textContent = "🏹 Hunting Grounds";
    document.getElementById("huntAgainBtn").onclick = () => { returnToHuntOverview(); renderPhaseFHunting(); };
    showHuntStep("result");
    if(currentEncounter?.bountyEncounter || currentEncounter?.bountyTrailEncounter){
      await refreshH2CLiveEvents(false);
      if(payload.caught && currentEncounter?.bountyEncounter){
        showActivityResult("🏆","Bounty Target Captured",
          `${currentEncounter.name} was captured with the normal Roll to Catch system. Return the trophy to complete the bounty.`);
      } else if(payload.caught && currentEncounter?.bountyTrailEncounter){
        const b=h2aLiveEvents?.bounty;
        showActivityResult("🔎","Bounty Clue Found",
          `You caught ${currentEncounter.name}. Your next Bounty Hunt now has a ${Number(b?.trackingChance||20)}% chance to find the actual target.`);
      }
    }
  } catch(error) {
    console.error("Activity capture request failed:",error);
    const status=document.getElementById("status");
    if(status) status.textContent=`❌ Capture connection failed: ${error.message}`;
  } finally {
    btn.disabled = false;
    btn.textContent = "🎲 Roll to Catch";
  }
}

boot();



// ==================== H.2D.2 BOUNTY UI FORCE FIX ====================
let h2dBusy=false;

function h2dWait(ms){
  const total=Math.max(0,Math.ceil(Number(ms||0)/1000));
  const h=Math.floor(total/3600);
  const m=Math.floor((total%3600)/60);
  const s=total%60;
  return h ? `${h}:${String(m).padStart(2,"0")}:${String(s).padStart(2,"0")}` : `${m}:${String(s).padStart(2,"0")}`;
}

function h2dBountyMarkup(){
  const b=h2aLiveEvents?.bounty;
  if(!b?.active) return "";
  const captured=b.status==="awaiting_turnin";
  const left=Math.max(0,Number(b.huntReadyAt||0)-Date.now());
  const ready=left<=0;

  const button=captured
    ? (b.canTurnIn
        ? `<button type="button" class="primary" id="h2dTurn">🏆 Return Trophy</button>`
        : `<button type="button" class="primary" disabled>🏆 Awaiting Trophy Return</button>`)
    : (ready
        ? `<button type="button" class="primary" id="h2dHunt">📜 Bounty Hunt</button>`
        : `<button type="button" class="primary" disabled>⏱️ Ready in ${h2dWait(left)}</button>`);

  return `
    <article class="hunt-zone-card" id="liveBountyHuntCard">
      <div class="hunt-zone-art">📜</div>
      <div class="hunt-zone-body">
        <p class="eyebrow">ACTIVE BOUNTY</p>
        <h3>${captured ? (b.targetName || "Target Captured") : "Target: UNKNOWN"}</h3>
        <p><strong>Posted by:</strong> ${b.npc || "Unknown Hunter"}</p>
        <p>🔎 ${b.clue || "The trail is still cold."}</p>
        <p>🎯 Your Target Chance: <strong>${Number(b.trackingChance||10)}%</strong> • 🧩 Clues: <strong>${Number(b.cluesFound||0)}</strong></p>
        <p>👥 ${Number(b.participants||0)} participating • 🏹 ${Number(b.attempts||0)} attempts</p>
        ${captured && b.trophy ? `<p>🏆 Trophy: <strong>${b.trophy}</strong></p>` : `<p>⏱️ Separate 60-minute Bounty cooldown.</p>`}
        ${button}
      </div>
    </article>`;
}

function h2dMountBountyCard(){
  const grid=document.getElementById("huntZoneGrid");
  const b=h2aLiveEvents?.bounty;
  if(!grid || !b?.active) return;

  document.getElementById("liveBountyHuntCard")?.remove();
  grid.insertAdjacentHTML("afterbegin",h2dBountyMarkup());

  document.getElementById("h2dHunt")?.addEventListener("click",h2dDoHunt);
  document.getElementById("h2dTurn")?.addEventListener("click",h2dDoTurnIn);
}

const h2dBaseRenderHunt=renderPhaseFHunting;
renderPhaseFHunting=function(){
  h2dBaseRenderHunt();
  h2dMountBountyCard();
};

async function h2dDoHunt(){
  if(h2dBusy) return;
  h2dBusy=true;
  try{
    const response=await activityFetch("/api/activity/bounty/hunt",{
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:"{}"
    });
    const payload=await response.json();
    if(!response.ok) throw new Error(payload.error||"Bounty Hunt failed.");

    if(payload.result==="clue"){
      showActivityResult("🔎","Bounty Trail",
        `You searched the trail but did not locate the target. ${payload.clue}`);
      await refreshH2CLiveEvents(false);
      renderPhaseFHunting();
      return;
    }

    if(payload.result!=="encounter" || !payload.monster){
      throw new Error("The bounty encounter could not be loaded.");
    }

    // The Bounty Hunt has only FOUND the monster. Nothing is auto-captured.
    // From here we use the exact same encounter -> capture item -> Roll to Catch UI.
    activeHuntZone={
      key:"bounty",
      name:payload.isTarget ? "Bounty Target" : "Bounty Trail",
      subtitle:payload.isTarget ? "Bounty Target Found" : "Bounty Trail Encounter"
    };
    huntAttemptNumber=1;
    currentEncounter={
      ...payload.monster,
      baseChance:Number(payload.baseChance||payload.monster.chance||30),
      image:payload.monster.imageUrl || (payload.monster.image ? `/assets/monsters/${payload.monster.image}` : null)
    };
    selectedHuntMethod=null;
    selectedCaptureTool=null;
    currentRoll=null;

    phaseFHunting.captureTools=(payload.choices||[]).map(c=>({
      key:c.itemKey||"none",
      name:c.itemKey?c.label:"Normal Hunt",
      icon:c.itemKey==="berry"?"🍓":c.itemKey==="honey"?"🍯":c.itemKey==="net"?"🕸️":c.itemKey==="masterCharm"?"🌟":"🏹",
      bonus:0,
      uses:c.itemKey?Number(hunter.captureItems?.[c.itemKey]||0):null,
      liveChance:c.chance
    }));

    populateEncounterPage();
    const catchChance=document.getElementById("encounterCatchChance");
    if(catchChance) catchChance.textContent=`${payload.chance}%`;
    showHuntStep("encounter");
  }catch(error){
    showActivityResult("❌","Bounty Hunt Failed",error.message);
  }finally{
    h2dBusy=false;
  }
}

async function h2dDoTurnIn(){
  if(h2dBusy) return;
  h2dBusy=true;
  try{
    const response=await activityFetch("/api/activity/bounty/turnin",{
      method:"POST",
      headers:{"Content-Type":"application/json"},
      body:"{}"
    });
    const payload=await response.json();
    if(!response.ok) throw new Error(payload.error||"Bounty turn-in failed.");

    showActivityResult("📜","Bounty Complete",
      `${payload.targetName} has been turned in. The next bounty arrives in 24 hours.`);
    await refreshH2CLiveEvents(false);
    renderPhaseFHunting();
  }catch(error){
    showActivityResult("❌","Turn-in Failed",error.message);
  }finally{
    h2dBusy=false;
  }
}

const h2dBaseRenderEvents=renderPhaseEEvents;
renderPhaseEEvents=function(){
  h2dBaseRenderEvents();

  const b=h2aLiveEvents?.bounty;
  const overview=document.querySelector(".event-overview-grid");
  if(!b?.active || !overview) return;

  document.getElementById("h2dEventBountyDetail")?.remove();
  overview.insertAdjacentHTML("beforeend",`
    <button class="event-summary bounty-summary" id="h2dEventBountyDetail">
      <div class="event-summary-art">📜</div>
      <div>
        <span class="live-dot">ACTIVE</span>
        <h3>${b.status==="awaiting_turnin" ? (b.targetName||"Target Captured") : "Active Bounty"}</h3>
        <p>${b.status==="awaiting_turnin" ? "Trophy return pending" : `🎯 Your target chance: ${Number(b.trackingChance||10)}% • 🧩 ${Number(b.cluesFound||0)} clues`}</p>
        <small>🔎 ${b.clue||""}</small>
      </div>
    </button>`);
  document.getElementById("h2dEventBountyDetail")?.addEventListener("click",()=>navTo("hunt"));
};

// Keep the bounty cooldown button fresh without requiring a full event reload.
setInterval(()=>{
  if(currentScreen==="hunt" && h2aLiveEvents?.bounty?.active){
    h2dMountBountyCard();
  }
},1000);

// ===== H.4 PLAYER NOTIFICATION PREFERENCES =====
const H4_NOTIFICATION_META = [
  {key:"huntReady",icon:"🏹",name:"Hunt Ready",detail:"Notify me in Discord when my normal Hunt cooldown ends.",kind:"Personal Alert"},
  {key:"eggReady",icon:"🥚",name:"Egg Ready",detail:"Notify me in Discord when one of my incubated eggs is ready to hatch.",kind:"Personal Alert"},
  {key:"fetchReady",icon:"🐾",name:"Fetch Alerts",detail:"Notify me when my companion is ready to use !fetch again.",kind:"Personal Alert"},
  {key:"huntAlerts",icon:"🏹",name:"Hunt Alerts",detail:"Give me the Discord Hunt Alerts role for general hunt announcements.",kind:"Role"},
  {key:"merchantAlerts",icon:"🛒",name:"Merchant Alerts",detail:"Ping me when a traveling merchant arrives.",kind:"Role"},
  {key:"bigHuntAlerts",icon:"👑",name:"Big Hunt Alerts",detail:"Ping me for Big Game warnings and starts.",kind:"Role"},
  {key:"bountyAlerts",icon:"🎯",name:"Bounty Alerts",detail:"Ping me when a new bounty is posted.",kind:"Role"},
  {key:"worldEventAlerts",icon:"🌌",name:"World Event Alerts",detail:"Ping me when major world events begin.",kind:"Role"}
];
let h4NotificationState=null;

function ensureH4NotificationPanel(){
  const home=document.querySelector('[data-screen="home"]');
  if(!home || document.getElementById("h4NotificationPanel")) return;
  const quick=home.querySelector(".quick-grid");
  const panel=document.createElement("section");
  panel.id="h4NotificationPanel";
  panel.className="panel h4-notification-panel";
  panel.innerHTML=`
    <div class="h4-notification-heading">
      <div><p class="eyebrow">🔔 NOTIFICATIONS</p><h3>Monster Hunt Alerts</h3></div>
      <span class="h4-notification-route" id="h4NotificationRoute">Loading…</span>
    </div>
    <p class="muted">Choose personal ready notifications and opt-in Discord event roles.</p>
    <div class="h4-notification-grid" id="h4NotificationGrid">
      <div class="empty-state">Loading notification preferences…</div>
    </div>`;
  if(quick) quick.insertAdjacentElement("beforebegin",panel);
  else home.appendChild(panel);
}

function renderH4NotificationPanel(){
  ensureH4NotificationPanel();
  const grid=document.getElementById("h4NotificationGrid");
  const route=document.getElementById("h4NotificationRoute");
  if(!grid||!h4NotificationState) return;
  route.textContent=h4NotificationState.testing?"🧪 Test channel active":"✅ Live channels active";
  const prefs=h4NotificationState.preferences||{};
  grid.innerHTML=H4_NOTIFICATION_META.map(item=>`
    <label class="h4-notification-row">
      <span class="h4-notification-icon">${item.icon}</span>
      <span class="h4-notification-copy"><b>${item.name}</b><small>${item.detail}</small><em>${item.kind}</em></span>
      <input class="h4-notification-toggle" type="checkbox" data-h4-notification="${item.key}" ${prefs[item.key]?"checked":""} />
      <span class="h4-toggle-visual" aria-hidden="true"></span>
    </label>`).join("");
  grid.querySelectorAll("[data-h4-notification]").forEach(input=>{
    input.addEventListener("change",async()=>{
      const key=input.dataset.h4Notification, enabled=input.checked;
      input.disabled=true;
      try{
        const response=await activityFetch("/api/activity/notifications",{
          method:"POST",
          headers:{"Content-Type":"application/json"},
          body:JSON.stringify({key,enabled})
        });
        const result=await response.json();
        if(!response.ok||!result.ok) throw new Error(result.error||"Could not update notification.");
        h4NotificationState.preferences={...(h4NotificationState.preferences||{}),...(result.preferences||{})};
        showActivityResult("🔔","Notifications Updated",enabled?"Alert enabled.":"Alert disabled.");
      }catch(error){
        input.checked=!enabled;
        showActivityResult("❌","Notification Update Failed",error.message);
      }finally{
        input.disabled=false;
      }
    });
  });
}

async function refreshH4NotificationPrefs(){
  ensureH4NotificationPanel();
  try{
    const response=await activityFetch("/api/activity/notifications");
    const result=await response.json();
    if(!response.ok||!result.ok) throw new Error(result.error||"Could not load notifications.");
    h4NotificationState=result;
    renderH4NotificationPanel();
  }catch(error){
    const grid=document.getElementById("h4NotificationGrid");
    if(grid) grid.innerHTML=`<div class="empty-state">❌ ${escapeHtml(error.message)}</div>`;
  }
}

setTimeout(()=>refreshH4NotificationPrefs().catch(()=>null),250);

